import { I18nextProvider } from 'react-i18next';
import { useTranslation } from 'react-i18next';
import { useEffect, useState } from 'react';
import i18n from '~/utils/i18n/config';

interface I18nProviderProps {
  children: React.ReactNode;
}

// Componente interno para inicializar i18next en el cliente
function I18nInitializer({ children }: I18nProviderProps) {
  const { i18n: i18nInstance } = useTranslation();
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    // i18next ya está inicializado desde config.ts
    setIsInitialized(true);
  }, [i18nInstance.language]);

  if (!isInitialized) {
    return <>{children}</>;
  }

  return <>{children}</>;
}

export function I18nProvider({ children }: I18nProviderProps) {
  return (
    <I18nextProvider i18n={i18n}>
      <I18nInitializer>{children}</I18nInitializer>
    </I18nextProvider>
  );
}

export function useI18n() {
  const { t, i18n } = require('react-i18next').useTranslation();
  return { t, i18n };
}

