// Compatibilidad hacia atrás
export const useLanguageContext = () => {
  const { t, i18n } = require('react-i18next').useTranslation();

  // Mantener estructura similar al contexto anterior
  return {
    state: {
      currentLanguage: i18n.language as 'es' | 'en',
      translations: {},
    },
    dispatch: (action: { type: string; payload: string }) => {
      if (action.type === 'SET_LANGUAGE') {
        i18n.changeLanguage(action.payload);
      }
    },
    t,
    i18n,
  };
};

export const LanguageContextProvider = I18nProvider;
